INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-001',unit_id,'quiz-topic-neuro-ap1','Em quantos grandes componentes anatómico-funcionais se divide o crânio?',NULL,'<strong>Do ponto de vista funcional e anatómico, os dois grandes componentes são o neurocrânio e o viscerocrânio.</strong> O neurocrânio, composto pela calota e pela base, envolve e protege o encéfalo e os órgãos dos sentidos especiais relacionados com olfação, visão, audição e equilíbrio.<p><small>Gray’s Anatomy, 42.ª ed., p. 288.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-001-answer','quiz-neuro-ap1-001','Neurocrânio e viscerocrânio',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-001-incorrect','quiz-neuro-ap1-001','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-002',unit_id,'quiz-topic-neuro-ap1','Que duas partes constituem o neurocrânio?',NULL,'O crânio é constituído pelo neurocrânio, pelo viscerocrânio ou esqueleto facial e pela mandíbula. <strong>O neurocrânio pode subdividir-se em calota craniana ou abóbada e base do crânio.</strong> Envolve o encéfalo, as porções intracranianas dos nervos cranianos, vasos sanguíneos, meninges e líquido cefalorraquidiano.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-002-answer','quiz-neuro-ap1-002','Calota craniana e base',1,1);
