INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-006',unit_id,'quiz-topic-neuro-ap1','Que componente do crânio forma o esqueleto da face?',NULL,'O neurocrânio, composto pela calota e pela base, envolve e protege o encéfalo e os órgãos dos sentidos especiais relacionados com olfação, visão, audição e equilíbrio. O <strong>viscerocrânio</strong> forma o esqueleto da face, palato e faringe, participa na alimentação, respiração e expressão facial, protege a língua e contribui para a formação do ouvido médio e da porção óssea do meato acústico externo.<p><small>Gray’s Anatomy, 42.ª ed., p. 288.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-006-answer','quiz-neuro-ap1-006','Viscerocrânio',1,1);
