INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-007',unit_id,'quiz-topic-neuro-ap1','Onde são mais frequentes os ossos suturais?',NULL,'Podem originar-se a partir de centros de ossificação separados e, em regra, não têm significado clínico direto, sendo a sua etiologia mais frequentemente genética do que patológica; admite-se que a sua formação inicial possa relacionar-se com tensão da dura-máter e aumento da largura sutural (Bellary et al., 2013). São mais frequentes na <strong>sutura lambdóide</strong>, a mais tortuosa das suturas, mas também se observam nas suturas sagital e coronal. Um grande osso interparietal mediano não é raro e é por vezes designado osso Inca.<p><small>Gray’s Anatomy, 42.ª ed., p. 560.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-007-answer','quiz-neuro-ap1-007','Sutura lambdóide',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-007-incorrect','quiz-neuro-ap1-007','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-008',unit_id,'quiz-topic-neuro-ap1','Como se designa um grande osso interparietal mediano sutural?',NULL,'São mais frequentes na sutura lambdóide, a mais tortuosa das suturas, mas também se observam nas suturas sagital e coronal. Um grande osso interparietal mediano não é raro e é por vezes designado <strong>osso Inca</strong>. Os ossos wormianos podem funcionar como marcadores de algumas doenças congénitas, incluindo osteogénese imperfeita e disostose cleidocraniana.<p><small>Gray’s Anatomy, 42.ª ed., p. 560.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-008-answer','quiz-neuro-ap1-008','Osso Inca',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-008-incorrect','quiz-neuro-ap1-008','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-009',unit_id,'quiz-topic-neuro-ap1','Entre que camadas se encontra o díploe?',NULL,'A maioria dos ossos da abóbada é achatada e constituída por duas lâminas de osso compacto, externa e interna, <strong>entre as quais existe uma camada de osso esponjoso relativamente denso, o díploe</strong>.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-009-answer','quiz-neuro-ap1-009','Lâminas externa e interna',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-009-incorrect','quiz-neuro-ap1-009','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-010',unit_id,'quiz-topic-neuro-ap1','Qual das lâminas da calota é mais fina e frágil?',NULL,'A <strong>lâmina interna</strong> é mais fina e mais frágil, enquanto a lâmina externa tende a ser mais espessa e mais resistente. Esta diferença é importante na avaliação de fraturas cranianas provocadas por traumatismo contuso ou penetrante.<p><small>Gray’s Anatomy, 42.ª ed., p. 558.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-010-answer','quiz-neuro-ap1-010','Lâmina interna',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-010-incorrect','quiz-neuro-ap1-010','Resposta não correspondente',2,0);
