INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-014',unit_id,'quiz-topic-neuro-ap1','Que cavidades pneumáticas centrais são visíveis no frontal, maxila e etmóide?',NULL,'Radiografias anteroposteriores do crânio mostram claramente a localização central dos <strong>seios paranasais</strong> no osso frontal, maxila e etmóide. Estes seios apresentam grande variabilidade anatómica individual, que pode ser suficientemente característica para auxiliar a identificação quando imagens post mortem são comparadas com exames realizados em vida.<p><small>Gray’s Anatomy, 42.ª ed., p. 560.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
